// Elevanlabs STT'den words değerini al
let words = [];
try {
  const elevanlabsOutput = $('elevanlabs STT').first().json;
  if (elevanlabsOutput && elevanlabsOutput.words && Array.isArray(elevanlabsOutput.words)) {
    words = elevanlabsOutput.words;
  } else {
    console.log('Uyarı: elevanlabs STT çıktısında words dizisi bulunamadı veya array değil');
  }
} catch (error) {
  console.log('Hata: elevanlabs STT çıktısı alınamadı:', error.message);
}

// Çağrı ID'sini al
let callid = 'unknown';
try {
  callid = $('get call file').first().json.callid || 'unknown';
} catch (error) {
  console.log('Uyarı: callid alınamadı:', error.message);
}

// Words dizisi boşsa boş sonuç döndür
if (!words.length) {
  return [
    {
      json: {
        callid: callid,
        conversation: [],
        error: 'Transkripsiyon verisi bulunamadı'
      }
    }
  ];
}

// Zaman sırasına göre sırala
const sortedWords = words.sort((a, b) => a.start - b.start);

const conversation = [];
let currentSpeaker = null;
let currentText = '';
let currentStart = null;
let currentEnd = null;
let conversationIndex = 0;

for (const word of sortedWords) {
  const speaker = word.speaker_id || 'unknown';
  const text = word.text || '';

  if (speaker !== currentSpeaker) {
    if (currentSpeaker !== null) {
      conversation.push({
        speaker: currentSpeaker,
        text: currentText.trim(),
        start: currentStart,
        end: currentEnd,
        conversation_index: conversationIndex++
      });
    }

    // Yeni konuşmacı başlat
    currentSpeaker = speaker;
    currentText = text;
    currentStart = word.start;
    currentEnd = word.end;
  } else {
    currentText += ' ' + text;
    currentEnd = word.end;
  }
}

// Son bloğu ekle
if (currentText.trim()) {
  conversation.push({
    speaker: currentSpeaker,
    text: currentText.trim(),
    start: currentStart,
    end: currentEnd,
    conversation_index: conversationIndex++
  });
}

return [
  {
    json: {
      callid: callid,
      conversation: conversation
    }
  }
];

