// Basic LLM Chain çıktısını düzgün JSON'a dönüştür
let item;
try {
  item = $input.first();
} catch (error) {
  console.log('Input alınamadı:', error.message);
  return [{
    json: {
      error: 'İşlem yapılamadı',
      callid: 'unknown'
    }
  }];
}

// Çağrı ID'sini al
let callid = 'unknown';
try {
  callid = $('get call file').first().json.callid || $('get conversation').first().json.callid || 'unknown';
} catch (error) {
  console.log('CallID bulunamadı:', error.message);
}

let output = {};

if (item.json && item.json.text) {
  let responseText = item.json.text;

  // Markdown JSON formatını temizle
  if (responseText.includes('```json')) {
    responseText = responseText.replace(/```json\n|```/g, '');
  }

  try {
    // JSON olarak parse et
    output = JSON.parse(responseText);
  } catch (error) {
    console.log('JSON parse hatası:', error.message);
    output = {
      error: 'JSON parse hatası',
      raw_text: responseText
    };
  }
}

// callid ekleyerek döndür
return [{
  json: {
    ...output,
    callid: callid
  }
}];
